import { expect, test } from "@e2e/fixtures";
import * as ui from "@e2e/ui-actions";

test.describe("Canvas states", () => {
  test.use({
    inspectorOptions: {
      inspectMode: true,
    },
  });

  test("No flow is currently active placeholder when flow stack is empty", async ({
    inspectorPage,
  }) => {
    await test.step("Assert no active flow placeholder", async () => {
      await ui.inspectorShell.actions(inspectorPage).restartConversation();
      const { noActiveFlowPlaceholder } = ui.inspectorCanvas.getLocators(inspectorPage);
      await expect
        .poll(async () => noActiveFlowPlaceholder.isVisible(), {
          message: "Flow panel should show the no-active-flow placeholder after restart",
          timeout: 15_000,
        })
        .toBe(true);
    });
  });

  test("Failed to load flows error when /data returns 500", async ({ inspectorPage }) => {
    await test.step("Intercept /data with 500 and assert flows error", async () => {
      await inspectorPage.route("**/data", (route) =>
        route.fulfill({ status: 500, body: "error" }),
      );
      await inspectorPage.reload();
      await ui.inspectorShell.assertions(inspectorPage).shellIsReady();
      await ui.inspectorShell.actions(inspectorPage).toggleInspectOn();
      await ui.inspectorCanvas.assertions(inspectorPage).inspectorCanvasIsVisible();
      await ui.inspectorCanvas.assertions(inspectorPage).flowsErrorIsVisible();
    });
  });
});
